import pandas as pd
from solver import Algorithm
from typing import Tuple, List, Dict


class Evolved(Algorithm):
    """
    Prefix-cache-optimized reorderer.

    Objective: maximize total matched characters in a character Trie over
    serialized rows ("" join of fillna("").astype(str) cell strings). For a
    fixed multiset of serialized row strings the ideal Trie reuse is the sum
    of LCPs of lexicographically adjacent sorted strings, so rows are always
    emitted in lexicographic order of their serialized form. The remaining
    lever is choosing each row's column order; several bounded candidate
    constructions are generated once each, scored with the exact sorted-LCP
    objective, and the best is returned.
    """

    def __init__(self, df: pd.DataFrame = None):
        self.df = df
        self.colstr: List[List[str]] = []
        self.max_depth = 5        # bounded conditional-tree depth
        self.cand_limit = 8       # bounded candidate columns per tree node

    # ---------- serialization ----------

    def _serialize(self, df: pd.DataFrame) -> None:
        """Serialize each column once into Python string lists (missing -> '')."""
        self.colstr = []
        for c in df.columns:
            out = []
            for v in df[c].tolist():
                if v is None or v is pd.NA or v is pd.NaT:
                    out.append("")
                elif isinstance(v, float) and v != v:
                    out.append("")
                else:
                    out.append(str(v))
            self.colstr.append(out)

    # ---------- scoring ----------

    @staticmethod
    def _lcp(a: str, b: str) -> int:
        """Longest common prefix via binary search using C-speed slice equality."""
        if a == b:
            return len(a)
        lo, hi = 0, min(len(a), len(b))
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if a[:mid] == b[:mid]:
                lo = mid
            else:
                hi = mid - 1
        return lo

    def _score_sorted(self, strs: List[str]) -> int:
        """Sum of adjacent LCPs of sorted row strings = exact serial Trie reuse."""
        total = 0
        prev = strs[0]
        for cur in strs[1:]:
            if cur == prev:
                total += len(cur)
            else:
                total += self._lcp(prev, cur)
            prev = cur
        return total

    # ---------- candidate constructions ----------

    def _rows_strings(self, row_ids: List[int], perms: List[Tuple[int, ...]]) -> List[str]:
        return ["".join(self.colstr[j][r] for j in perm) for r, perm in zip(row_ids, perms)]

    def _finalize(self, row_ids, perms) -> Tuple[List[int], List[Tuple[int, ...]]]:
        """Sort rows lexicographically by serialized string (optimal row order)."""
        pairs = sorted(zip(self._rows_strings(row_ids, perms), row_ids, perms), key=lambda t: t[0])
        return [p[1] for p in pairs], [p[2] for p in pairs]

    def _cand_identity(self, n: int, ncol: int):
        """Original column order as a cheap baseline."""
        perm = tuple(range(ncol))
        return self._finalize(list(range(n)), [perm] * n)

    def _global_weights(self, row_ids, ncol, pair: bool):
        """Column weight = sum over values of len(v)*pairs among rows, where
        pairs = c-1 (linear) or c*(c-1) (quadratic emphasis on repetition)."""
        weights = []
        for j in range(ncol):
            col = self.colstr[j]
            cnt: Dict[str, int] = {}
            wsum: Dict[str, int] = {}
            for r in row_ids:
                v = col[r]
                cnt[v] = cnt.get(v, 0) + 1
                wsum[v] = wsum.get(v, 0) + len(v)
            w = 0
            for v, c in cnt.items():
                if c > 1:
                    w += wsum[v] * (c * (c - 1) if pair else (c - 1))
            weights.append(w)
        return weights

    def _cand_freq(self, row_ids: List[int], ncol: int, pair: bool = False):
        """Global column order ranked by length-weighted repetition, deterministic ties."""
        weights = self._global_weights(row_ids, ncol, pair)
        order = sorted(range(ncol), key=lambda j: (-weights[j], j))
        return self._finalize(row_ids, [tuple(order)] * len(row_ids))

    def _useful(self, row_ids: List[int], j: int) -> bool:
        """Skip columns that cannot contribute shared prefix characters."""
        col = self.colstr[j]
        seen = set()
        for r in row_ids[:64]:
            seen.add(col[r])
        return len(seen) > 1

    def _cand_tree(self, row_ids: List[int], ncol: int, quadratic: bool = False):
        """Conditional prefix partition: recursively pick a shared leading
        column by length-weighted repetition gain, partition rows on its
        serialized value, and order suffixes separately per group.
        quadratic=True weights repetitions by c*(c-1) (a distinct hypothesis
        from the linear c-1 gain). Stops when reuse disappears or depth caps."""

        def node(rows: List[int], remaining: List[int], prefix: Tuple[int, ...]):
            if len(rows) < 2 or not remaining or len(prefix) >= self.max_depth:
                return [(prefix + tuple(remaining), rows)]
            best_j, best_gain = None, 0.0
            for j in remaining[: self.cand_limit]:
                if not self._useful(rows, j):
                    continue
                cnt: Dict[str, int] = {}
                wsum: Dict[str, int] = {}
                for r in rows:
                    v = self.colstr[j][r]
                    cnt[v] = cnt.get(v, 0) + 1
                    wsum[v] = wsum.get(v, 0) + len(v)
                g = 0.0
                for v, c in cnt.items():
                    if c > 1:
                        g += wsum[v] * (c * (c - 1) if quadratic else (c - 1))
                if g > best_gain:
                    best_gain, best_j = g, j
            if best_j is None:
                return [(prefix + tuple(remaining), rows)]
            groups: Dict[str, List[int]] = {}
            for r in rows:
                groups.setdefault(self.colstr[best_j][r], []).append(r)
            rem = [j for j in remaining if j != best_j]
            out = []
            for key in sorted(groups):
                if len(groups[key]) > 1:
                    out.extend(node(groups[key], rem, prefix + (best_j,)))
                else:
                    out.append((prefix + (best_j,) + tuple(rem), groups[key]))
            return out

        perms: List[Tuple[int, ...]] = [None] * len(row_ids)
        for perm, rows in node(row_ids, list(range(ncol)), ()):
            for r in rows:
                perms[r] = perm
        return self._finalize(row_ids, perms)

    # ---------- public API ----------

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge: List[List[str]] = [],
        one_way_dep: List[Tuple[str, str]] = [],
        distinct_value_threshold: float = 0.8,
        parallel: bool = True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Produce the row/field ordering maximizing serial character-Trie reuse."""
        if col_merge:
            self.num_rows, self.column_stats = self.calculate_col_stats(df, enable_index=True)
            reordered_columns = [c for c, _, _, _ in self.column_stats]
            for col_to_merge in col_merge:
                final_col_order = [c for c in reordered_columns if c in col_to_merge]
                df = self.merging_columns(df, final_col_order, prepended=False)

        n, ncol = df.shape
        cols = list(df.columns)
        if n == 0 or ncol == 0:
            return df.copy(), [[] for _ in range(n)]

        self._serialize(df)
        raw = df.astype(object).values.tolist()
        row_ids = list(range(n))

        # Bounded construction selection: at most four whole-program candidates,
        # each scored once with the exact sorted-LCP character objective.
        candidates = [self._cand_identity(n, ncol), self._cand_freq(row_ids, ncol)]
        if n * ncol <= 4_000_000:
            candidates.append(self._cand_tree(row_ids, ncol, quadratic=False))
            candidates.append(self._cand_tree(row_ids, ncol, quadratic=True))

        best = None
        best_score = -1
        for row_order, perms in candidates:
            strs = self._rows_strings(row_order, perms)
            score = self._score_sorted(strs)
            if score > best_score:
                best_score = score
                best = (row_order, perms)

        row_order, perms = best

        # Assemble output: object dtype preserves mixed types; every original
        # value retained, each row placed in its own column permutation.
        data = []
        orderings = []
        for r, perm in zip(row_order, perms):
            data.append([raw[r][j] for j in perm])
            orderings.append([cols[j] for j in perm])
        out = pd.DataFrame(data, columns=[f"c{i}" for i in range(ncol)], dtype=object)
        return out, orderings

